<template><section><h3>商业口径试算</h3><p>仅展示本版本的计算口径，不产生订单、资金快照或渠道操作。</p><label>商品实付（元）<Input v-model="product" placeholder="例如 100.01"/></label><label>运费（元，不计佣金）<Input v-model="shipping" placeholder="例如 5.00"/></label><Button :loading="loading" @click="preview">试算当前版本</Button><p v-if="error" class="s1-error">{{error}}</p><p v-if="result">佣金 {{money(result.commissionCent)}}；商户商品余款 {{money(result.merchantProductCent)}}。依据规则版本 {{result.revision}}。</p></section></template>
<script>
import {s1Read} from '@/api/stage1';import {money} from './shared';
function cents(value){if(!/^(0|[1-9][0-9]*)(\.[0-9]{1,2})?$/.test(value))throw Error('请输入最多两位小数的非负金额。');const [whole,fraction='']=value.split('.'),amount=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(!Number.isSafeInteger(amount)||amount>99999999)throw Error('金额不能超过999999.99元。');return amount;}
export default {props:{rule:{type:Object,required:true}},data:()=>({product:'',shipping:'',loading:false,error:'',result:null,ticket:0}),watch:{rule(){this.ticket++;this.result=null;}},beforeDestroy(){this.ticket++;},methods:{money,async preview(){const ticket=++this.ticket;this.loading=true;this.error='';this.result=null;try{const value=await s1Read('/commission-rules/'+this.rule.id+'/preview',{productPaidCent:cents(this.product),shippingCent:cents(this.shipping)});if(ticket===this.ticket)this.result=value;}catch(e){if(ticket===this.ticket)this.error=e.message;}finally{if(ticket===this.ticket)this.loading=false;}}}};
</script><style scoped>section{padding:18px;border:1px solid #e8eaec}label{display:inline-block;width:230px;margin:12px 18px 12px 0}.s1-error{color:#c8292f}</style>
